-- Roulette review: a processing reason is optional for both apply and ignore.
create or replace function public.resolve_event(p_id uuid,p_data jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;e public.roulette_events;a uuid;processing_reason text:=coalesce(trim(p_data->>'reason'),'');begin perform public.assert_admin();r=public.operation_begin('event.resolve',p_key,jsonb_build_object('id',p_id,'data',p_data));if r is not null then return r;end if;select * into e from public.roulette_events where id=p_id for update;if not found or e.status<>'review_required' then raise exception 'REVIEW_ALREADY_RESOLVED' using errcode='40001';end if;
 if (p_data->>'ignore')::boolean then update public.roulette_events set status='ignored',reason=processing_reason where id=p_id;
 else if not coalesce((p_data->>'verified')::boolean,false) then raise exception 'CONFIRM_REQUIRED';end if;a=public.ensure_account(p_data->>'soop',p_data->>'nickname',(p_data->>'typeId')::uuid);perform public.append_ledger(a,(p_data->>'quantity')::numeric,'roulette',processing_reason,p_id);update public.roulette_events set status='applied',reason=processing_reason where id=p_id;end if;perform public.audit('event.resolve',p_id::text);return public.operation_finish('event.resolve',p_key,jsonb_build_object('id',p_id));end$$;
